 36	export class OrderRepository {
 37	  findByUser(userId) {
 38	    return new Promise((resolve, reject) => {
 39	      query('orders', (o) => o.user_id === userId && o.deleted_at === null,
 40	        (err, rows) => (err ? reject(err) : resolve(rows)));
 41	    });
 42	  }
 43	
 44	  findPaid() {
 45	    return new Promise((resolve, reject) => {
 46	      query('orders', (o) => o.status === 'paid' && o.deleted_at === null,
 47	        (err, rows) => (err ? reject(err) : resolve(rows)));
 48	    });
 49	  }
 50	}
 51	// A deliberately tiny in-memory database with a callback API.
 52	// The callback style is the point: Chapter 5 migrates the service layer off it.
 53	
 54	const tables = {
 55	  users: [
 56	    { id: 1, email: 'ada@example.com', name: 'Ada', deleted_at: null },
 57	    { id: 2, email: 'grace@example.com', name: 'Grace', deleted_at: null },
 58	    { id: 3, email: 'alan@example.com', name: 'Alan', deleted_at: '2026-01-04' },
 59	  ],
 60	  orders: [
 61	    { id: 10, user_id: 1, total_cents: 4200, status: 'paid', deleted_at: null },
 62	    { id: 11, user_id: 1, total_cents: 1350, status: 'quote', deleted_at: null },
 63	    { id: 12, user_id: 2, total_cents: 9900, status: 'paid', deleted_at: null },
 64	    { id: 13, user_id: 3, total_cents: 500, status: 'paid', deleted_at: null },
 65	  ],
 66	  payments: [
 67	    { id: 100, order_id: 10, amount_cents: 4200, captured: true },
 68	    { id: 101, order_id: 12, amount_cents: 9900, captured: false },
 69	  ],
 70	};
 71	
 72	export function reset() {
 73	  tables.users[2].deleted_at = '2026-01-04';
 74	  tables.orders.forEach((o) => { o.deleted_at = null; });
 75	}
 76	
 77	// Old-style callback query. Accepts a table name and a predicate.
 78	export function query(table, predicate, callback) {
 79	  setImmediate(() => {
 80	    const rows = tables[table];
 81	    if (!rows) return callback(new Error(`no such table: ${table}`));
 82	    try {
 83	      callback(null, rows.filter(predicate).map((r) => ({ ...r })));
 84	    } catch (err) {
 85	      callback(err);
 86	    }
 87	  });
 88	}
 89	
 90	export function update(table, id, patch, callback) {
 91	  setImmediate(() => {
 92	    const row = (tables[table] || []).find((r) => r.id === id);
 93	    if (!row) return callback(new Error(`no row ${id} in ${table}`));
 94	    Object.assign(row, patch);
 95	    callback(null, { ...row });
 96	  });
 97	}
